import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"54、【歸妹】 兌下震上","description":"周易尚氏學 - 54、【歸妹】 兌下震上","frontmatter":{"title":"54、【歸妹】 兌下震上","description":"周易尚氏學 - 54、【歸妹】 兌下震上"},"headers":[],"relativePath":"classics/shangshi/059.md","filePath":"classics/shangshi/059.md"}'),s={name:"classics/shangshi/059.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_54、【歸妹】-兌下震上" tabindex="-1">54、【歸妹】 兌下震上 <a class="header-anchor" href="#_54、【歸妹】-兌下震上" aria-label="Permalink to “54、【歸妹】 兌下震上”">​</a></h1><p>兌為少女。故曰妹。震為歸。婦人謂嫁曰歸。故曰歸妹。震類長女從長男為恆。則曰利有攸往。茲少女從長男。與恆同耳。乃彖義則與恆相反。曰徵兇無攸利何為也。曰恆下巽。巽陰承陽。與上震無一爻不相應。故利有攸往。歸妹則巽覆為兌。陰乘陽。初三皆失應。故徵兇。巽為利。巽覆故無攸利。又中四爻皆不當位。貞靜自守。尚恐有咎。動則悔吝生矣。故徵兇不利也。下系雲。其為道也屢遷。變動不居。周流六虛。上下無常。剛柔相易。不可為典要。唯變所適。正謂此。恆與歸妹。上卦同也。下卦同為二陽一陰也。乃巽則如彼。巽覆則如此。唯變所適也。唯變所適。謂甲卦與乙卦。一爻變動。則吉凶相反。非謂卦無是象。強命某爻變。以成其象也。自漢以來。因誤解變動不居。唯變所適二語。援為護符。浪用爻變。以濟其窮。前有虞翻。後有焦循。其尤也。</p><p>彖曰。歸妹。天地之大義也。天地不交。而萬物不興。歸妹。人之終始也。說以動。所歸妹也。徵兇。位不當也。無攸利。柔乘剛也。</p><p>歸妹而後有夫婦。天地者夫婦之義。天地交而後有萬物。故歸妹為女之終。生人之始。中爻皆不當位。三五皆以柔乘剛。故徵兇無攸利也。</p><p>象曰。澤上有雷。歸妹。君子以水終知敝。</p><p>女歸則永終。兌毀折。故以知敝為戒。</p><p>初九。歸妹以娣。破能履。徵吉。</p><p>初在兌下。故曰梯。娣者嫡之女弟也。公羊傳。諸侯一聘九女。嫁者一娣一侄（左女）。騰者皆有至娣。嫁者謂嫡。嫡及兩媵六娃娣共九女。兌折震故跛。然二升五則下成震。震為足。故曰跛能履。徵吉也。象曰吉相承。即承二升五而吉也。</p><h3 id="象曰。歸妹以娣。以恆也。跛能履。吉相承也。" tabindex="-1">象曰。歸妹以娣。以恆也。跛能履。吉相承也。 <a class="header-anchor" href="#象曰。歸妹以娣。以恆也。跛能履。吉相承也。" aria-label="Permalink to “象曰。歸妹以娣。以恆也。跛能履。吉相承也。”">​</a></h3><p>按初無應。二陽為阻。不能前進。有兇無吉。茲曰吉相承。謂二升五下卦成震。初臨重陰。相隨而吉。相承者謂二升五吉。初承其後仍吉也。虞翻求其義而不得。強命初爻變陰承陽為說。夫初當位。胡能使變。經義之不明。此等曲說亂之也。以恆蓋謂女嫁隨娃梯。乃娶婦之常道。說者動以恆卦為解。非。</p><p>九二。眇能視。利幽人之貞。</p><p>二三米高，故曰眇。說文。眇一眇也。能者。以互離也。二應國五，五展為人。克為昧。故曰幽人。利幽人之貞。言利與互相上下。各當位也。</p><h3 id="象曰-利幽人之貞。未變常也。" tabindex="-1">象曰，利幽人之貞。未變常也。 <a class="header-anchor" href="#象曰-利幽人之貞。未變常也。" aria-label="Permalink to “象曰，利幽人之貞。未變常也。”">​</a></h3><p>未變常。言二五相應與乃常道也。</p><p>六三。歸妹以須。反歸以娣。</p><p>須。說文面毛也。歸嫁也。歸妹為嫡。今以須之故。反嫁為娣也。伏艮為須。易林同人之否雲。牽於虎鬚。否互艮為虎為須。虞氏訓須為需。需待也。六三若有待義。與九四之有待義復矣。易林渙之歸妹雲。妹為貌執（下心）。敗君正色。莊子田子子方老聃新沐。方將被髮而乾。華然似非人。華言可怖也。是焦氏亦訓須為面毛也。故曰貌華。</p><h3 id="象曰。歸妹以須。未當也。" tabindex="-1">象曰。歸妹以須。未當也。 <a class="header-anchor" href="#象曰。歸妹以須。未當也。" aria-label="Permalink to “象曰。歸妹以須。未當也。”">​</a></h3><p>未當言不宜有是惡象也。困上六當位矣。象曰未當也。義與此同。革傳曰革而當。義皆同宜。後雅麗堂集解本見虞注作位未當。竟於象傳添一位字。豈知正文若作位未當。釋文早言之矣。今釋文無有。可證虞本亦無位字。雅麗本皆從惠棟校。改字甚多。昔人謂惠氏亂經。茲更添字。宜罪之者多也。</p><p>九四。歸妹愆期。返歸有時。</p><p>震為時。坎陷故愆期。愆過也。愆期故遲歸待時。待升五也。又下無應。亦衍期之一因。卦四時俱備。故曰有時。升五則時至矣。</p><h3 id="象曰。想期之志。有待而行也。" tabindex="-1">象曰。想期之志。有待而行也。 <a class="header-anchor" href="#象曰。想期之志。有待而行也。" aria-label="Permalink to “象曰。想期之志。有待而行也。”">​</a></h3><p>坎為志。震為行。有待而行者。待升五也。</p><p>六五。帝已歸妹。其君之袂。不如其娣之袂良。月既望吉。</p><p>震為帝。故曰帝乙。帝乙湯也。京房易載基嫁妹之辭。是湯曾嫁妹。故曰帝乙歸妹。震為君為袂。而震亦為口。袂袖口也。袂在五震。故日君袂。在二兌。故曰棵袂。皆取象於口。乃五陰二陽。故君袂不如姊良。坎為月。為中。震東兌西。坎月離日。東西相望。正望日也。惟五居坎末。時已過中。故曰既望。既望從孟、荀讀。虞作幾。京作近。晁說之雲。古文近既讀同。孟雲既望者。十六日也。五得中有應故吉。震君震袂震口象皆失傳。說詳焦氏易詁。</p><h3 id="象曰。帝已歸妹。不如其梯之袂良也。其位在中。以貴行也。" tabindex="-1">象曰。帝已歸妹。不如其梯之袂良也。其位在中。以貴行也。 <a class="header-anchor" href="#象曰。帝已歸妹。不如其梯之袂良也。其位在中。以貴行也。" aria-label="Permalink to “象曰。帝已歸妹。不如其梯之袂良也。其位在中。以貴行也。”">​</a></h3><p>雖不正而得中。中五位尊。故曰貴。</p><p>站長：孟、荀可能是指孟喜和荀爽，他們是西漢時期的易學家。應該當作「既望」，巽也為月始缺，如小畜「既雨既處...月既望」同理。</p><p>上六。女筐無實。士刲羊無血。無攸利。</p><p>下兌為女。震為筐。女在下。筐在上。故曰女承筐。乃上不應三。故無實。震為虛。亦無實也。震為士。兌為羊。為斧。為毀折。故曰士刲羊。乃三不應上。故無血。坎為血。三體離。坎伏。故無血。此與失九二。因爻無應。即就無應取義。舊解坐不知此。故說之永不能通。巽為利。巽伏上下失應。故無攸利。震虛象失傳。虞翻用卦變成坤。取虛象。豈知震為蒼茛竹為葦。皆取其中虛。況象傳曰虛筐。亦以震為虛。</p><h3 id="象曰。上六元實。承虛筐也。" tabindex="-1">象曰。上六元實。承虛筐也。 <a class="header-anchor" href="#象曰。上六元實。承虛筐也。" aria-label="Permalink to “象曰。上六元實。承虛筐也。”">​</a></h3><p>象明言震虛。故知虞氏非。</p>',31)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
